<script setup>
import {ref,onMounted} from 'vue';import {Menu,Search,Bell,Home,PlaySquare,Bookmark,Newspaper,WifiOff,MapPin,Download} from 'lucide-vue-next';
const open=ref(false),online=ref(navigator.onLine),installEvent=ref(null);
onMounted(()=>{window.addEventListener('online',()=>online.value=true);window.addEventListener('offline',()=>online.value=false);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent.value=e})});
async function install(){if(installEvent.value){await installEvent.value.prompt();installEvent.value=null}}
</script>
<template><div class="app-shell"><div v-if="!online" class="offline-banner"><WifiOff/> Offline mode · Reading downloaded news</div><header class="mobile-header"><button class="round-btn" @click="open=!open"><Menu/></button><router-link class="pulse-logo" to="/"><span>P</span><div><b>PULSE</b><small>ગુજરાત</small></div></router-link><div class="top-actions"><button v-if="installEvent" class="round-btn" @click="install"><Download/></button><button class="round-btn"><Bell/></button></div></header><div class="location-strip"><MapPin/> રાજકોટ <b>·</b> સ્થાનિક સમાચાર <span>27°C</span></div><main><router-view/></main><nav class="app-bottom"><router-link to="/"><Home/><span>હોમ</span></router-link><router-link to="/shorts"><PlaySquare/><span>શોર્ટ્સ</span></router-link><button class="center-news"><Newspaper/></button><a><Bookmark/><span>સેવ</span></a><router-link to="/polls"><Search/><span>શોધ</span></router-link></nav></div></template>